{
  "name": "串口实验I/O控制器",
  "name_en": "Serial Laboratory I/O Controller",
  "manufacturer": "",
  "description": "这是一类通过串口通信的通用实验室I/O控制器，可提供数字输出、模拟输出、脉冲/闪烁控制、舵机控制，以及模拟量和温度读取功能。它常用于显微镜和实验装置中的外设联动与自动化控制，例如驱动快门、激光相关部件、振动机构或读取传感器信号。",
  "description_en": "This is a general-purpose laboratory I/O controller that communicates over a serial port. It provides digital outputs, analog outputs, flash/pulse-style control, servo control, and analog and temperature readback. It is commonly used for peripheral coordination and automation in microscopes and other lab setups, such as driving shutters, laser-related components, shaking mechanisms, or reading sensor signals.",
  "tag_hints": [
    "serial I/O control",
    "laboratory automation",
    "digital output",
    "analog output",
    "servo control",
    "temperature sensing",
    "microcontroller interface"
  ],
  "actions": [
    {
      "action_name": "auto-SetDigital",
      "description": "设置指定通道的数字输出状态。",
      "description_en": "Set the digital output state of the specified channel."
    },
    {
      "action_name": "auto-SetAnalog",
      "description": "设置指定通道的模拟输出值。",
      "description_en": "Set the analog output value of the specified channel."
    },
    {
      "action_name": "auto-SetFlash",
      "description": "设置指定通道的闪烁/脉冲输出参数。",
      "description_en": "Set the flash/pulse output parameter of the specified channel."
    },
    {
      "action_name": "auto-SetServo",
      "description": "设置指定通道的舵机控制值。",
      "description_en": "Set the servo control value of the specified channel."
    },
    {
      "action_name": "auto-GetAnalog",
      "description": "读取指定通道的模拟输入值。",
      "description_en": "Read the analog input value of the specified channel."
    },
    {
      "action_name": "auto-GetTemperature",
      "description": "读取指定通道的温度值。",
      "description_en": "Read the temperature value of the specified channel."
    }
  ]
}

